import React from 'react';
import {
    Card,
    CardContent,
    Typography,
    Box,
    Alert,
    AlertTitle,
    Collapse,
    IconButton,
    Skeleton,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { Alert as AlertType } from '../../types';
import { getTimeAgo } from '../../utils/formatters';

interface AlertPanelProps {
    alerts: AlertType[];
    loading?: boolean;
    maxVisible?: number;
}

const AlertPanel: React.FC<AlertPanelProps> = ({
    alerts,
    loading = false,
    maxVisible = 3,
}) => {
    const [expanded, setExpanded] = React.useState(false);

    const handleExpandClick = () => {
        setExpanded(!expanded);
    };

    const visibleAlerts = expanded ? alerts : alerts.slice(0, maxVisible);
    const hasMoreAlerts = alerts.length > maxVisible;

    if (loading) {
        return (
            <Card>
                <CardContent>
                    <Skeleton variant="text" width="30%" height={32} />
                    <Skeleton variant="rectangular" width="100%" height={80} sx={{ mt: 2, borderRadius: 2 }} />
                    <Skeleton variant="rectangular" width="100%" height={80} sx={{ mt: 2, borderRadius: 2 }} />
                </CardContent>
            </Card>
        );
    }

    if (alerts.length === 0) {
        return (
            <Card>
                <CardContent sx={{ p: 3 }}>
                    <Typography variant="h5" fontWeight={700} gutterBottom>
                        System Alerts
                    </Typography>
                    <Alert severity="success" sx={{ mt: 2 }}>
                        <AlertTitle>All Systems Normal</AlertTitle>
                        No alerts at this time. All stockpile levels are within expected ranges.
                    </Alert>
                </CardContent>
            </Card>
        );
    }

    return (
        <Card>
            <CardContent sx={{ p: 3 }}>
                <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                    <Typography variant="h5" fontWeight={700}>
                        System Alerts
                    </Typography>
                    {hasMoreAlerts && (
                        <Typography variant="body2" color="text.secondary" fontWeight={600}>
                            {alerts.length} total
                        </Typography>
                    )}
                </Box>

                <Box>
                    {visibleAlerts.map((alert, index) => (
                        <Alert
                            key={alert.id}
                            severity={alert.severity}
                            sx={{
                                mb: index < visibleAlerts.length - 1 ? 2 : 0,
                                borderRadius: 2,
                                '& .MuiAlert-message': {
                                    width: '100%',
                                },
                            }}
                        >
                            <AlertTitle sx={{ fontWeight: 700 }}>
                                {alert.severity === 'error'
                                    ? 'Critical Alert'
                                    : alert.severity === 'warning'
                                        ? 'Warning'
                                        : 'Information'}
                            </AlertTitle>
                            <Typography variant="body2">{alert.message}</Typography>
                            <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                                {getTimeAgo(alert.timestamp)}
                            </Typography>
                        </Alert>
                    ))}

                    {hasMoreAlerts && (
                        <Box textAlign="center" mt={2}>
                            <IconButton
                                onClick={handleExpandClick}
                                sx={{
                                    transform: expanded ? 'rotate(180deg)' : 'rotate(0deg)',
                                    transition: 'transform 0.3s',
                                }}
                            >
                                <ExpandMoreIcon />
                            </IconButton>
                            <Typography variant="body2" color="text.secondary" fontWeight={600}>
                                {expanded ? 'Show less' : `Show ${alerts.length - maxVisible} more`}
                            </Typography>
                        </Box>
                    )}
                </Box>
            </CardContent>
        </Card>
    );
};

export default AlertPanel;
